import { useEffect, useState, type FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { CalendarDays, ChevronRight, Clock3, Droplets, Edit3, Plus, Sprout, Trash2, Users } from 'lucide-react';
import { apiRequest, ApiError } from '../../api/client';
import { useAuth } from '../../auth/AuthContext';
import { useToast } from '../../components/ToastContext';
import { Badge, Button, Card, EmptyState, ErrorState, Field, Input, LoadingState, Modal, PageHeader, Select, Textarea } from '../../components/ui';
import { itemId, itemLabel, useCatalog } from '../../hooks/useCatalog';
import type { Pasture, PastureDetail } from '../../types/api';
import { formatDate, formatNumber, nullIfEmpty, numberOrNull } from '../../utils';

interface GrassForm { id_tipo_pasto: string; porcentaje_estimado: string; area_estimada: string; id_unidad_area: string; fecha_siembra: string; observaciones: string }
interface PastureForm { nombre: string; codigo: string; descripcion: string; activo: boolean; area: string; id_unidad_area: string; id_tipo_uso_potrero: string; capacidad_estimada: string; disponibilidad_agua: boolean; fecha_ultimo_descanso: string; observaciones: string; pastos: GrassForm[] }
const empty: PastureForm = { nombre: '', codigo: '', descripcion: '', activo: true, area: '', id_unidad_area: '', id_tipo_uso_potrero: '', capacidad_estimada: '', disponibilidad_agua: true, fecha_ultimo_descanso: '', observaciones: '', pastos: [] };

function PastureModal({ pasture, onClose }: { pasture?: Pasture | null; onClose: () => void }) {
  const toast = useToast(); const client = useQueryClient(); const [form, setForm] = useState<PastureForm>(empty);
  const uses = useCatalog('usos-potrero'); const grasses = useCatalog('pastos'); const units = useCatalog('unidades');
  useEffect(() => setForm(pasture ? { nombre: pasture.nombre, codigo: pasture.codigo ?? '', descripcion: pasture.descripcion ?? '', activo: pasture.activo, area: pasture.area?.toString() ?? '', id_unidad_area: pasture.id_unidad_area ?? '', id_tipo_uso_potrero: pasture.id_tipo_uso_potrero, capacidad_estimada: pasture.capacidad_estimada?.toString() ?? '', disponibilidad_agua: pasture.disponibilidad_agua ?? false, fecha_ultimo_descanso: pasture.fecha_ultimo_descanso ?? '', observaciones: pasture.observaciones ?? '', pastos: pasture.pastos.map((item) => ({ id_tipo_pasto: item.id_tipo_pasto, porcentaje_estimado: item.porcentaje_estimado?.toString() ?? '', area_estimada: item.area_estimada?.toString() ?? '', id_unidad_area: item.id_unidad_area ?? '', fecha_siembra: item.fecha_siembra ?? '', observaciones: item.observaciones ?? '' })) } : empty), [pasture]);
  useEffect(() => { if (!form.id_tipo_uso_potrero && uses.data?.length) setForm((x) => ({ ...x, id_tipo_uso_potrero: itemId(uses.data![0]) })); }, [uses.data, form.id_tipo_uso_potrero]);
  const mutation = useMutation({ mutationFn: () => apiRequest(pasture ? `/potreros/${pasture.id_potrero}` : '/potreros', { method: pasture ? 'PATCH' : 'POST', body: { ubicacion: { nombre: form.nombre, codigo: nullIfEmpty(form.codigo), descripcion: nullIfEmpty(form.descripcion), activo: form.activo }, area: numberOrNull(form.area), id_unidad_area: form.id_unidad_area || null, id_tipo_uso_potrero: form.id_tipo_uso_potrero, capacidad_estimada: numberOrNull(form.capacidad_estimada), disponibilidad_agua: form.disponibilidad_agua, fecha_ultimo_descanso: form.fecha_ultimo_descanso || null, observaciones: nullIfEmpty(form.observaciones), pastos: form.pastos.map((item) => ({ id_tipo_pasto: item.id_tipo_pasto, porcentaje_estimado: numberOrNull(item.porcentaje_estimado), area_estimada: numberOrNull(item.area_estimada), id_unidad_area: item.id_unidad_area || null, fecha_siembra: item.fecha_siembra || null, observaciones: nullIfEmpty(item.observaciones) })) } }), onSuccess: async () => { toast.show(pasture ? 'Potrero actualizado.' : 'Potrero creado.'); await client.invalidateQueries({ queryKey: ['pastures'] }); await client.invalidateQueries({ queryKey: ['locations'] }); onClose(); }, onError: (error) => toast.show((error as ApiError).message, 'error') });
  const addGrass = () => setForm((x) => ({ ...x, pastos: [...x.pastos, { id_tipo_pasto: grasses.data?.[0] ? itemId(grasses.data[0]) : '', porcentaje_estimado: '', area_estimada: '', id_unidad_area: x.id_unidad_area, fecha_siembra: '', observaciones: '' }] }));
  return <Modal title={pasture ? 'Editar potrero' : 'Nuevo potrero'} onClose={onClose} wide footer={<><Button variant="ghost" onClick={onClose}>Cancelar</Button><Button form="pasture-form" type="submit" loading={mutation.isPending}>Guardar</Button></>}><form id="pasture-form" className="form-stack" onSubmit={(event: FormEvent) => { event.preventDefault(); mutation.mutate(); }}><div className="form-section"><h3>Información del potrero</h3><div className="form-grid"><Field label="Nombre" required><Input value={form.nombre} onChange={(e) => setForm((x) => ({ ...x, nombre: e.target.value }))} required /></Field><Field label="Código"><Input value={form.codigo} onChange={(e) => setForm((x) => ({ ...x, codigo: e.target.value }))} /></Field><Field label="Área"><Input type="number" step="0.01" min="0" value={form.area} onChange={(e) => setForm((x) => ({ ...x, area: e.target.value }))} /></Field><Field label="Unidad de área"><Select value={form.id_unidad_area} onChange={(e) => setForm((x) => ({ ...x, id_unidad_area: e.target.value }))}><option value="">Sin unidad</option>{units.data?.map((item) => <option key={itemId(item)} value={itemId(item)}>{itemLabel(item)} {item.simbolo ? `(${String(item.simbolo)})` : ''}</option>)}</Select></Field><Field label="Tipo de uso" required><Select value={form.id_tipo_uso_potrero} onChange={(e) => setForm((x) => ({ ...x, id_tipo_uso_potrero: e.target.value }))} required>{uses.data?.map((item) => <option key={itemId(item)} value={itemId(item)}>{itemLabel(item)}</option>)}</Select></Field><Field label="Capacidad estimada"><Input type="number" min="0" value={form.capacidad_estimada} onChange={(e) => setForm((x) => ({ ...x, capacidad_estimada: e.target.value }))} /></Field><Field label="Último descanso"><Input type="date" value={form.fecha_ultimo_descanso} onChange={(e) => setForm((x) => ({ ...x, fecha_ultimo_descanso: e.target.value }))} /></Field><Field label="Disponibilidad de agua"><Select value={String(form.disponibilidad_agua)} onChange={(e) => setForm((x) => ({ ...x, disponibilidad_agua: e.target.value === 'true' }))}><option value="true">Sí</option><option value="false">No</option></Select></Field></div><Field label="Descripción"><Textarea rows={2} value={form.descripcion} onChange={(e) => setForm((x) => ({ ...x, descripcion: e.target.value }))} /></Field><Field label="Observaciones"><Textarea rows={2} value={form.observaciones} onChange={(e) => setForm((x) => ({ ...x, observaciones: e.target.value }))} /></Field></div><div className="form-section"><div className="section-heading-inline"><h3>Tipos de pasto</h3><Button type="button" variant="secondary" onClick={addGrass}><Plus size={17} />Agregar pasto</Button></div>{form.pastos.length === 0 ? <p className="muted">Aún no se han agregado pastos.</p> : <div className="nested-list">{form.pastos.map((grass, index) => <div className="nested-card" key={`${grass.id_tipo_pasto}-${index}`}><div className="nested-card-header"><strong>Pasto {index + 1}</strong><Button type="button" variant="ghost" onClick={() => setForm((x) => ({ ...x, pastos: x.pastos.filter((_, i) => i !== index) }))}><Trash2 size={17} />Quitar</Button></div><div className="form-grid"><Field label="Tipo de pasto" required><Select value={grass.id_tipo_pasto} onChange={(e) => setForm((x) => ({ ...x, pastos: x.pastos.map((item, i) => i === index ? { ...item, id_tipo_pasto: e.target.value } : item) }))}>{grasses.data?.map((item) => <option key={itemId(item)} value={itemId(item)}>{itemLabel(item)}</option>)}</Select></Field><Field label="Porcentaje estimado"><Input type="number" min="0" max="100" step="0.01" value={grass.porcentaje_estimado} onChange={(e) => setForm((x) => ({ ...x, pastos: x.pastos.map((item, i) => i === index ? { ...item, porcentaje_estimado: e.target.value } : item) }))} /></Field><Field label="Área estimada"><Input type="number" min="0" step="0.01" value={grass.area_estimada} onChange={(e) => setForm((x) => ({ ...x, pastos: x.pastos.map((item, i) => i === index ? { ...item, area_estimada: e.target.value } : item) }))} /></Field><Field label="Unidad"><Select value={grass.id_unidad_area} onChange={(e) => setForm((x) => ({ ...x, pastos: x.pastos.map((item, i) => i === index ? { ...item, id_unidad_area: e.target.value } : item) }))}><option value="">Sin unidad</option>{units.data?.map((item) => <option key={itemId(item)} value={itemId(item)}>{itemLabel(item)}</option>)}</Select></Field><Field label="Fecha de siembra"><Input type="date" value={grass.fecha_siembra} onChange={(e) => setForm((x) => ({ ...x, pastos: x.pastos.map((item, i) => i === index ? { ...item, fecha_siembra: e.target.value } : item) }))} /></Field></div></div>)}</div>}</div></form></Modal>;
}

export function PasturesPage() {
  const { hasPermission } = useAuth(); const [editing, setEditing] = useState<Pasture | null | undefined>(undefined); const [detailId, setDetailId] = useState<string | null>(null);
  const query = useQuery({ queryKey: ['pastures'], queryFn: () => apiRequest<Pasture[]>('/potreros') });
  const detail = useQuery({ queryKey: ['pastures', detailId, 'summary'], queryFn: () => apiRequest<PastureDetail>(`/potreros/${detailId}/resumen`), enabled: Boolean(detailId) });
  const openEdit = (pasture: Pasture) => { setDetailId(null); setEditing(pasture); };
  return <div>
    <PageHeader title="Potreros" description="Consulta ocupación, descanso, pastos e historial de cada potrero." action={hasPermission('POTRERO_ADMINISTRAR') ? <Button onClick={() => setEditing(null)}><Plus size={18} />Nuevo potrero</Button> : undefined} />
    {query.isLoading ? <LoadingState /> : query.isError ? <ErrorState message={(query.error as Error).message} onRetry={() => void query.refetch()} /> : query.data?.length === 0 ? <EmptyState icon={Sprout} title="Sin potreros" description="Registra el primer potrero de la propiedad." /> : <Card className="pasture-list">
      <div className="pasture-list-head"><span>Potrero</span><span>Área</span><span>Pastos</span><span>Estado actual</span><span /></div>
      {query.data?.map((pasture) => <button type="button" className="pasture-list-row" key={pasture.id_potrero} onClick={() => setDetailId(pasture.id_potrero)}>
        <span className="pasture-name"><span className="pasture-mini-icon"><Sprout size={18} /></span><span><strong>{pasture.nombre}</strong><small>{pasture.tipo_uso}{pasture.codigo ? ` · ${pasture.codigo}` : ''}</small></span></span>
        <span><strong>{pasture.area != null ? `${formatNumber(pasture.area)}${pasture.unidad_area ? ` ${pasture.unidad_area}` : ''}` : 'Sin registrar'}</strong><small>{pasture.capacidad_estimada != null ? `Capacidad: ${pasture.capacidad_estimada}` : 'Sin capacidad'}</small></span>
        <span className="pasture-grass-summary"><strong>{pasture.pastos.length ? pasture.pastos.map((item) => item.pasto).filter(Boolean).join(', ') : 'Sin pastos'}</strong><small>{pasture.pastos.length} {pasture.pastos.length === 1 ? 'tipo registrado' : 'tipos registrados'}</small></span>
        <span><Badge tone={Number(pasture.total_animales) > 0 ? 'info' : 'success'}>{Number(pasture.total_animales) > 0 ? 'Ocupado' : 'En descanso'}</Badge><small>{Number(pasture.total_animales)} animales</small></span>
        <span className="pasture-row-actions">{hasPermission('POTRERO_ADMINISTRAR') ? <Button variant="ghost" onClick={(event) => { event.stopPropagation(); openEdit(pasture); }}><Edit3 size={16} /><span>Editar</span></Button> : null}<ChevronRight size={19} /></span>
      </button>)}
    </Card>}
    {detailId ? <Modal title="Detalle del potrero" onClose={() => setDetailId(null)} wide footer={detail.data && hasPermission('POTRERO_ADMINISTRAR') ? <Button onClick={() => openEdit(detail.data)}><Edit3 size={17} />Editar potrero</Button> : undefined}>
      {detail.isLoading ? <LoadingState /> : detail.isError ? <ErrorState message={(detail.error as Error).message} onRetry={() => void detail.refetch()} /> : detail.data ? <PastureDetailContent pasture={detail.data} /> : null}
    </Modal> : null}
    {editing !== undefined ? <PastureModal pasture={editing} onClose={() => setEditing(undefined)} /> : null}
  </div>;
}

function PastureDetailContent({ pasture }: { pasture: PastureDetail }) {
  const status = pasture.ocupacion.estado;
  return <div className="pasture-detail">
    <div className="pasture-detail-heading"><div className="record-icon"><Sprout size={23} /></div><div><h2>{pasture.nombre}</h2><p>{pasture.tipo_uso}{pasture.codigo ? ` · ${pasture.codigo}` : ''}</p></div><Badge tone={status === 'OCUPADO' ? 'info' : 'success'}>{status === 'OCUPADO' ? 'Ocupado' : 'En descanso'}</Badge></div>
    <div className="pasture-summary-grid">
      <div><Sprout size={19} /><span><small>Área</small><strong>{pasture.area != null ? `${formatNumber(pasture.area)}${pasture.unidad_area ? ` ${pasture.unidad_area}` : ''}` : 'Sin registrar'}</strong></span></div>
      <div><Users size={19} /><span><small>Animales actuales</small><strong>{pasture.ocupacion.total_animales}</strong></span></div>
      <div><CalendarDays size={19} /><span><small>Última ocupación</small><strong>{formatDate(pasture.ocupacion.fecha_ultima_ocupacion)}</strong></span></div>
      <div><Clock3 size={19} /><span><small>Días de última ocupación</small><strong>{pasture.ocupacion.dias_ultima_ocupacion ?? '—'}</strong></span></div>
      <div><CalendarDays size={19} /><span><small>Último descanso</small><strong>{formatDate(pasture.ocupacion.fecha_ultimo_descanso)}</strong></span></div>
      <div><Clock3 size={19} /><span><small>{status === 'DESCANSO' ? 'Días en descanso' : 'Duración del último descanso'}</small><strong>{pasture.ocupacion.dias_descanso ?? '—'}</strong></span></div>
      <div><Droplets size={19} /><span><small>Agua</small><strong>{pasture.disponibilidad_agua ? 'Disponible' : 'No disponible'}</strong></span></div>
      <div><Users size={19} /><span><small>Capacidad estimada</small><strong>{pasture.capacidad_estimada ?? '—'}</strong></span></div>
    </div>
    <section className="pasture-detail-section"><h3>Pastos</h3><div className="pasture-grass-list">{pasture.pastos.length ? pasture.pastos.map((grass) => <div key={grass.id_potrero_pasto ?? grass.id_tipo_pasto}><strong>{grass.pasto}</strong><span>{grass.porcentaje_estimado != null ? `${grass.porcentaje_estimado}% estimado` : 'Porcentaje no registrado'}{grass.area_estimada != null ? ` · ${formatNumber(grass.area_estimada)} de área` : ''}</span></div>) : <p className="muted">Sin pastos registrados.</p>}</div></section>
    {(pasture.descripcion || pasture.observaciones) ? <section className="pasture-detail-section"><h3>Información adicional</h3>{pasture.descripcion ? <p>{pasture.descripcion}</p> : null}{pasture.observaciones ? <p className="muted">{pasture.observaciones}</p> : null}</section> : null}
    <section className="pasture-detail-section"><div className="section-heading-inline"><div><h3>Historial de ocupaciones</h3><p className="muted">Cada período muestra el descanso que tuvo el potrero antes de ser ocupado.</p></div></div>{pasture.historial_ocupaciones.length ? <div className="pasture-history-table"><div className="pasture-history-head"><span>Ocupación</span><span>Duración</span><span>Animales</span><span>Descanso previo</span></div>{pasture.historial_ocupaciones.map((period, index) => <div className="pasture-history-row" key={`${period.inicio}-${index}`}><span><strong>{formatDate(period.inicio)}</strong><small>hasta {period.fin ? formatDate(period.fin) : 'la actualidad'}</small></span><span><strong>{period.dias_ocupacion} días</strong></span><span><strong>{period.total_animales}</strong></span><span><strong>{period.dias_descanso_previo != null ? `${period.dias_descanso_previo} días` : 'Sin dato previo'}</strong><small>{period.descanso_previo_desde ? `desde ${formatDate(period.descanso_previo_desde)}` : ''}</small></span></div>)}</div> : <EmptyState icon={CalendarDays} title="Sin historial" description="Este potrero todavía no registra períodos de ocupación." />}</section>
  </div>;
}
